"""Fused NPU zero-copy kernels, generated by text edits of the Lite sources.
  fu_pre.comp  = pre_lds.comp (Lite prepass) + a second store of every int8 word, ^0x80, straight into the layer's dma-buf in the NPU input
                 layout (dense 960x540x16 uint8; uvec4 index qin + x + 960y): replaces the pack dispatch.
  fu_k1*.comp  = b1_0009.comp (Lite K1) reading the NPU outputs from the dma-buf instead of the scratch buffer: value = sat_int8(pixelshuffle(out0)
                 + out1), zero outside the image (the unpack halo). Modes: lds = 18x18 uvec4 LDS tile per 16x16 group (fu_k1), soa = the same tile as
                 4 uint arrays (fu_k1s), dir = every tap and the centre skip read and add the dma-buf directly (fu_k1d).
  npu_select_fu.comp = npu_select.comp with the arguments of the GPU K1 (words 25..27) and the fused K1 (words 28..30).
usage: gen_fu.py <pre_lds.comp> <b1_0009.comp> <npu_select.comp> <out dir>"""
import sys, re
PRE, K1, SEL, O = sys.argv[1:5]
DECL_T = lambda ty, ro: ('layout(set = 1, binding = 0, std430) %s buffer FuT { %s; } fuT;\n'
                         'layout(push_constant) uniform FuP { uint qin, q0, q1, pad; } fuP;\n') % (ro, ty)
anchor = '} ScratchBuffer;\n'

# ---- prepass + pack
s = open(PRE).read()
assert s.count(anchor) == 1
s = s.replace(anchor, anchor + '\n' + DECL_T('uint w[]', 'writeonly'), 1)
st = '        ScratchBuffer._m0[_2305 + g] = pk;\n'
assert s.count(st) == 2
s = s.replace(st, st + '        if (uint(_2288.x) < 960u && uint(_2288.y) < 540u) fuT.w[4u * (fuP.qin + uint(_2288.x) + 960u * uint(_2288.y)) + g] = pk ^ 0x80808080u;\n')
open(O + '/fu_pre.comp', 'w', newline='\n').write(s)

# ---- K1 + unpack
PX = '''uint fu_addsat(uint a, uint b) {
  uint o = 0u;
  for (int k = 0; k < 4; k++) { int s = bitfieldExtract(int(a), 8 * k, 8) + bitfieldExtract(int(b), 8 * k, 8); o = bitfieldInsert(o, uint(clamp(s, -128, 127)), 8 * k, 8); }
  return o;
}
uvec4 fu_px(uint ux, uint uy) {
  uvec4 a = fuT.q[fuP.q0 + ((uy >> 1) * 480u + (ux >> 1)) * 4u + (uy & 1u) * 2u + (ux & 1u)] ^ uvec4(0x80808080u);
  uvec4 b = fuT.q[fuP.q1 + uy * 960u + ux] ^ uvec4(0x80808080u);
  return uvec4(fu_addsat(a.x, b.x), fu_addsat(a.y, b.y), fu_addsat(a.z, b.z), fu_addsat(a.w, b.w));
}
'''
def k1(mode, fname):
    s = open(K1).read()
    SH = {'lds': 'shared uvec4 fuTile[324];\n', 'soa': 'shared uint fuT0[324], fuT1[324], fuT2[324], fuT3[324];\n', 'dir': ''}[mode]
    assert s.count(anchor) == 1
    s = s.replace(anchor, anchor + '\n' + DECL_T('uvec4 q[]', 'readonly') + SH, 1)
    fns = PX
    if mode == 'lds': fns += 'void fu_st(uint i, uvec4 v) { fuTile[i] = v; }\nuvec4 fu_ld(uint i) { return fuTile[i]; }\n'
    if mode == 'soa': fns += ('void fu_st(uint i, uvec4 v) { fuT0[i] = v.x; fuT1[i] = v.y; fuT2[i] = v.z; fuT3[i] = v.w; }\n'
                              'uvec4 fu_ld(uint i) { return uvec4(fuT0[i], fuT1[i], fuT2[i], fuT3[i]); }\n')
    if mode != 'dir': fns += '''void fu_fill(uint i) {
  uvec2 fo = gl_WorkGroupID.xy * 16u; int x = int(fo.x + i % 18u) - 1, y = int(fo.y + i / 18u) - 1; uvec4 v = uvec4(0u);
  if (x >= 0 && y >= 0 && x < 960 && y < 540) v = fu_px(uint(x), uint(y));
  fu_st(i, v);
}
'''
    m = 'void main()\n{\n'
    assert s.count(m) == 1
    pro = '' if mode == 'dir' else '    fu_fill(gl_LocalInvocationID.x);\n    if (gl_LocalInvocationID.x < 68u) fu_fill(gl_LocalInvocationID.x + 256u);\n    barrier();\n'
    s = s.replace(m, fns + m + pro, 1)
    tap = re.compile(r'uint ba = \(\(\(16u \* uint\(tc\.x \+ 1\)\) \+ \(15392u \* uint\(tc\.y \+ 1\)\)\) \+ 16684928u\) >> 2u;')
    n = len(tap.findall(s)); assert n == 9, n
    if mode == 'dir': s = tap.sub('uvec4 fv = fu_px(uint(tc.x), uint(tc.y));', s)   # inside the in-image predicate
    else: s = tap.sub('uvec4 fv = fu_ld(uint(tc.y + 1 - int(gl_WorkGroupID.y * 16u)) * 18u + uint(tc.x + 1 - int(gl_WorkGroupID.x * 16u)));', s)
    for k in range(4):
        c = s.count('ScratchBuffer._m0[ba + %du]' % k); assert c == 9, (k, c)
        s = s.replace('ScratchBuffer._m0[ba + %du]' % k, 'fv[%d]' % k)
    sk = '        uvec4 _2446 = uvec4(_1225) + uvec4(1u, 1u, 0u, 0u);\n'
    assert s.count(sk) == 1
    cen = 'fu_px(_1216.x, _1216.y)' if mode == 'dir' else 'fu_ld(((_1216.y % 16u) + 1u) * 18u + (_1216.x % 16u) + 1u)'
    s = s.replace(sk, sk + '        uvec4 fc = %s;\n' % cen)
    for k, v in enumerate(['_2458', '_2461', '_2464', '_2467']):
        c = s.count('ScratchBuffer._m0[%s]' % v); assert c >= 1, (v, c)
        s = s.replace('ScratchBuffer._m0[%s]' % v, 'fc[%d]' % k)
    open(O + '/' + fname, 'w', newline='\n').write(s)
k1('lds', 'fu_k1.comp'); k1('soa', 'fu_k1s.comp'); k1('dir', 'fu_k1d.comp')

# ---- select: 0.8.1 words 0..24 unchanged; K1 GPU args (25..27, network rule) and K1 fused args (28..30, unpack rule)
sel = open(SEL).read()
a = '  live.a[24] = n ? 1u : 0u; }'
assert sel.count(a) == 1
sel = sel.replace(a, '  live.a[24] = n ? 1u : 0u;\n  for (uint i = 25u; i < 31u; i++) live.a[i] = ((i < 28u) != n) ? full.a[i] : 0u; }')
open(O + '/npu_select_fu.comp', 'w', newline='\n').write(sel)
print('gen_fu ok')
